        size_t nc = m->globals.cap ? m->globals.cap * 2 : 4;
        m->globals.data = runtime.realloc(m->globals.data, nc * sizeof(IRGlobal));
        if (!m->globals.data) { runtime.fprintf(runtime.stderr, "fakecc: OOM\n"); runtime.exit(1); }
        m->globals.cap = nc;
