        g->fixups = runtime.realloc(g->fixups, nc * sizeof(GlobalFixup));
        if (!g->fixups) { runtime.fprintf(runtime.stderr, "fakecc: OOM\n"); runtime.exit(1); }
        g->cap_fixups = (int)nc;
