        for (int i = 0; i < n; i++) body_label[i] = new_label(fn);
        int exit_label = new_label(fn);
        int ndispatch = 0;
        for (int i = 0; i < n; i++)
            if (!s->u.switch_s.cases[i].is_default) ndispatch++;
